/**
 * Shapes drawn from the real view south from Zug (src/data/skyline.json,
 * generated by tools/terrain/panorama.py).
 */
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

export const sceneData = JSON.parse(
  readFileSync(fileURLToPath(new URL('../data/skyline.json', import.meta.url)), 'utf8'),
);

const round = (v) => Math.round(v * 10) / 10;

function theta(layer, az) {
  const f = (az - sceneData.az0) / layer.step;
  const i = Math.max(0, Math.min(layer.th.length - 2, Math.floor(f)));
  const t = Math.min(1, Math.max(0, f - i));
  return (layer.th[i] * (1 - t) + layer.th[i + 1] * t) / 100;
}

/** The skyline: the highest of all layers at an azimuth. */
const skyline = (az) => Math.max(...sceneData.layers.map((l) => theta(l, az)));

/**
 * The outline of the range, from the Rigi across the Alps to Pilatus, as the
 * top edge of a content sheet: a path in a 1000 x 64 box, filled to the bottom.
 */
export function ridgeEdgePath({ from = 183, to = 231, points = 320 } = {}) {
  const samples = [];
  for (let i = 0; i <= points; i += 1) samples.push(skyline(from + ((to - from) * i) / points));
  const lo = Math.min(...samples);
  const hi = Math.max(...samples);
  const d = samples
    .map((th, i) => `${i ? 'L' : 'M'}${round((i / points) * 1000)} ${round(62 - ((th - lo) / (hi - lo)) * 58)}`)
    .join('');
  return `${d}L1000 64L0 64Z`;
}

/** Layer paths for a still drawing, from azimuth c0 - span to c0 + span. */
function layerPaths({ W, hy, k, ex, c0, span, fills, step }) {
  const x = (az) => round(W / 2 + (az - c0) * k);
  const y = (th) => round(hy - th * k * ex);
  return sceneData.layers
    .map((layer, i) => {
      const pts = [];
      for (let az = c0 - span; az <= c0 + span; az += step) pts.push(`${x(az)} ${y(theta(layer, az))}`);
      return { i, d: `M${x(c0 - span)} ${hy + 1}L${pts.join('L')}L${x(c0 + span)} ${hy + 1}Z` };
    })
    .reverse()
    .map(({ i, d }) => `<path fill="${fills[i]}" d="${d}"/>`)
    .join('');
}

/**
 * A still drawing of the same view at dusk, shown behind the page until the
 * live scene starts (and in place of it without JavaScript).
 */
export function staticBackdropSvg() {
  const W = 1600;
  const H = 1000;
  const hy = 640;
  const paths = layerPaths({
    W, hy, k: W / 78, ex: 1.6, c0: 207, span: 41, step: 0.1,
    fills: ['#1f2733', '#2c3546', '#4a5068', '#6c6c86', '#8f8ba2'],
  });
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${H}" preserveAspectRatio="xMidYMax slice">
<defs>
<linearGradient id="s" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#1a2848"/><stop offset=".55" stop-color="#6b6788"/><stop offset="1" stop-color="#e3a98c"/></linearGradient>
<linearGradient id="l" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#8a7488"/><stop offset="1" stop-color="#121a2c"/></linearGradient>
</defs>
<rect width="${W}" height="${hy + 1}" fill="url(#s)"/>${paths}<rect y="${hy}" width="${W}" height="${H - hy}" fill="url(#l)"/>
</svg>
`;
}

/**
 * The social sharing image: the same view at sunset, the sky orange beside
 * Pilatus, mirrored in the lake, with the wordmark in the sky. Rendered to
 * PNG by tools/render-images.mjs.
 */
export function ogImageSvg(wordmarkSvg) {
  const W = 1200;
  const H = 630;
  const hy = 440;
  const k = W / 72;
  const c0 = 206;
  const paths = layerPaths({
    W, hy, k, ex: 1.6, c0, span: 37, step: 0.1,
    fills: ['#1c2532', '#283244', '#3f4a62', '#5f6680', '#8a8ca6'],
  });
  const sunX = round(W / 2 + (241 - c0) * k);
  // The wordmark's own viewBox, scaled into the sky.
  const vb = (wordmarkSvg.match(/viewBox="([^"]+)"/) || [])[1].split(/\s+/).map(Number);
  const inner = wordmarkSvg.replace(/^[\s\S]*?<svg[^>]*>/, '').replace(/<\/svg>\s*$/, '');
  const ww = 400;
  const s = ww / vb[2];
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${H}" width="${W}" height="${H}">
<defs>
<linearGradient id="s" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#5b6f96"/><stop offset=".5" stop-color="#c98c74"/><stop offset="1" stop-color="#f08c45"/></linearGradient>
<linearGradient id="l" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#c8876e" stop-opacity=".5"/><stop offset="1" stop-color="#1a1d2c" stop-opacity=".94"/></linearGradient>
<radialGradient id="g" cx="${sunX}" cy="${hy - 30}" r="560" gradientUnits="userSpaceOnUse"><stop offset="0" stop-color="#ffc35a" stop-opacity=".85"/><stop offset=".35" stop-color="#ffb04a" stop-opacity=".3"/><stop offset="1" stop-color="#ffb04a" stop-opacity="0"/></radialGradient>
</defs>
<rect width="${W}" height="${hy + 1}" fill="url(#s)"/>
<rect width="${W}" height="${hy + 1}" fill="url(#g)"/>
<g color="#f6f3ee" transform="translate(${(W - ww) / 2} 70) scale(${round(s * 10000) / 10000}) translate(${-vb[0]} ${-vb[1]})">${inner}</g>
${paths}
<g transform="matrix(1 0 0 -0.8 0 ${round(1.8 * hy)})" opacity=".9">${paths}</g>
<rect y="${hy}" width="${W}" height="${H - hy}" fill="url(#l)"/>
</svg>
`;
}
